{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Integrates model-based and model-free values into a single net value for stage 1 choices using a weighting parameter.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseveration bonus to the stage 1 action chosen on the previous trial, independent of reward.",
      "params": [
        {
          "name": "rep",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\n        if last_action_1 != -1:\n            stickiness[last_action_1] = 1\n            \n        logits_1 = beta * q_stage1_net + rep * stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free Q-value using the stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[a1] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
